    "api",
    `repos/${args.repo}/issues/comments/${args.commentId}`,
    "--method",
    "PATCH",
    "-f",
    `body=${body}`,
  );
  if (updated.code !== 0) {
    console.error(`could not append the footer: ${updated.stderr || updated.stdout}`);
    return;
  }
  console.error(`footer appended to the ending comment ${args.commentId}`);
